import torch


def run_correctness(inp, t1, t2, value):
    result = torch.ops.aten.addcmul_(
        inp.float(), t1.float(), t2.float(), value=value
    )
    inp.copy_(result.to(inp.dtype))
    return inp


def run(inp, t1, t2, value):
    return torch.ops.aten.addcmul_(inp, t1, t2, value=value)
